fn solve(x: i32) -> i32 {
    // Count how many digits k x has, and extract its repeated digit d.
    let mut tmp = x;
    let mut k = 0;
    while tmp > 0 {
        k += 1;
        tmp /= 10;
    }
    // Since x is a repetition of the same digit, x % 10 gives us that digit.
    let d = x % 10;

    // For each digit i < d, we have the lengths 1+2+3+4 = 10 presses.
    // That contributes (d-1)*10.
    // Then for digit d itself, we only go up to length k, which costs 1+2+...+k = k*(k+1)/2.
    (d - 1) * 10 + k * (k + 1) / 2
}

